                                uint8_t                 escape;
                                fr_sbuff_marker_t       m;

                                fr_sbuff_marker(&m, &our_in);           /* allow for backtrack */

                                if (fr_sbuff_out_uint8_oct(NULL, &escape, &our_in, false) != 3) {
                                        fr_sbuff_set(&our_in, &m);      /* backtrack */
                                        fr_sbuff_marker_release(&m);
                                        goto check_subs;                /* allow sub for \<oct> */
                                }

